extra_css:
.status::before{width:11px;height:11px;box-sizing:border-box;border:2px solid var(--color-ink);background:transparent}
.status--now::before{background:var(--color-ink)}
.status--dev::before{background:linear-gradient(90deg,var(--color-ink) 50%,transparent 50%)}
.status--prep::before{}
.status--later::before{border:2px dotted var(--color-ink)}

@media (forced-colors: active){.status::before{forced-color-adjust:none;border-color:CanvasText}
 .status--now::before{background:CanvasText}.status--dev::before{background:linear-gradient(90deg,CanvasText 50%,transparent 50%)}}
/* branch = name + NATIVE border style (survives forced colours, zoom, one-colour print). Implementation: data-branch, not [style*=] */
[style*="--cable-soirees"]{--cable-style:solid}
[style*="--cable-reseau"]{--cable-style:double}
[style*="--cable-organiser"]{--cable-style:dashed}
[style*="--cable-apprendre"]{--cable-style:dotted}
[style*="--cable-tekpractice"]{--cable-style:dotted}

.door{border-top:5px var(--cable-style,solid) #16163F}
.branch-hero .cable{height:0;width:96px;background:none;border-top:5px var(--cable-style,solid) #16163F}
.board tbody th a{border-bottom:4px var(--cable-style,solid) #16163F;padding-bottom:4px}
.signup{border-top:5px var(--cable-style,solid) #16163F}
.site-footer{--focus-color:#FAFAF7}
.branch-hero[style*="--cable-soirees"]{background:#16163F;color:#FAFAF7;padding-block:72px;--focus-color:#FAFAF7;--color-ink:#FAFAF7;--color-ink-2:#D2D2E4;--color-ink-3:#D2D2E4;--color-signal:#FF8A4C}
.branch-hero[style*="--cable-soirees"] .cable{border-top-color:#FF8A4C}
